/*
 * Since we are passing DebugDelete() to a shared_ptr as a deleter, it will be
 * executed every time the shared_ptr's reference counter reaches 0
*/ 

#include <fstream>
#include <iostream>
#include "16.22.h" //  QueryResult

int main(int argc, char **argv)
{
