// Exercise 16.28. Write your own versions of shared_ptr and unique_ptr.

#ifndef DEBUG_DELETER_H
#define DEBUG_DELETER_H

#include <iostream>
#include <memory>

class DebugDeleter {
    public:
        DebugDeleter(std::ostream &s = std::cerr) : os(s) {} 
        template <typename T> void operator()(T *p) const
        { os << "DebugDeleter()" << std::endl; delete p; }
    private:
        std::ostream &os;
};

#endif // DEBUG_DELETER_H

/*
 * NOTE: This implementation is modelled on cppreference.org specifications.
 * Refer to https://en.cppreference.com/w/cpp/memory/shared_ptr
 * To simplify the code, the implementation uses a small set of key operations,
 * such as get, swap, operator boo() to perform the other operations. The
 * deleter is stored indirectly as a library function template type, which
 * handles the pointer to the function and its memory management automatically.
 */

#ifndef SHARED_PTR_H
#define SHARED_PTR_H

#include <functional>
#include <memory>
#include <ostream>

template <typename T>
class shared_ptr {
    public:
        shared_ptr() = default; // uses in-class initialization
        shared_ptr(std::nullptr_t) noexcept {} // converting constructor
        explicit shared_ptr(T* ptr, std::function<void(T*)> f = nullptr)
                    : p(ptr), del(f), use(new std::size_t(1)) {}
        shared_ptr(const shared_ptr& ptr) noexcept; // copy constructor
        shared_ptr(shared_ptr&&) noexcept; // move constructor
        ~shared_ptr(); // destructor
        shared_ptr& operator=(const shared_ptr&) noexcept; // copy-assignment op
        shared_ptr& operator=(shared_ptr&&) noexcept; // move-assignment op
        T* get() const noexcept { return p; }
        operator bool() const noexcept { return this->get() != nullptr; }
        void swap(shared_ptr&) noexcept;
        bool unique() const noexcept { return this->use_count() == 1; }
        std::size_t use_count() const noexcept { return (!*this) ? 0 : *use; }
        void reset() noexcept;
        void reset(T*, std::function<void(T*)> d = nullptr);
        T& operator*() const noexcept { return *this->get(); }
        T* operator->() const noexcept { return & this->operator*(); }
    private:
        T *p = nullptr; // built-in pointer
        std::function<void(T*)> del = nullptr; // callable deleter
        std::size_t *use = nullptr; // reference counter
        void decr_n_free();
};

template <typename T>
inline shared_ptr<T>::shared_ptr(const shared_ptr& ptr) noexcept :
                p(ptr.p), del(ptr.del), use(ptr.use)
{
    if (*this)
        ++*use;
}

template <typename T>
inline shared_ptr<T>::shared_ptr(shared_ptr&& ptr) noexcept :
                p(ptr.p), del(ptr.del), use(ptr.use)
{
    ptr.p = nullptr;
    ptr.del = nullptr;
    ptr.use = nullptr;
}

template <typename T>
inline shared_ptr<T>&
shared_ptr<T>::operator=(const shared_ptr &rhs) noexcept
{
    if (this != &rhs) {
        if (*this)
            decr_n_free();
        shared_ptr<T>(rhs).swap(*this);
    }
    return *this;
}

template <typename T>
inline shared_ptr<T>& shared_ptr<T>::operator=(shared_ptr&& rhs) noexcept
{
    if (this != &rhs) {
        if (*this)
            decr_n_free();
        shared_ptr<T>(std::move(rhs)).swap(*this);
    }
    return *this;
}

template <typename T>
inline shared_ptr<T>::~shared_ptr<T>()
{
    if (*this)
        decr_n_free();
}

template <typename T>
inline void shared_ptr<T>::swap(shared_ptr<T>& r) noexcept
{
    using std::swap;
    swap(p, r.p);
    swap(use, r.use);
    swap(del, r.del);
}

template <typename T>
inline void shared_ptr<T>::reset() noexcept
{
    shared_ptr<T>().swap(*this); 
}

template <typename T>
inline void shared_ptr<T>::reset(T* q, std::function<void(T*)> d)
{
    shared_ptr<T>(q, d).swap(*this); 
}

template <typename T>
inline void shared_ptr<T>::decr_n_free()
{
    if (--*use == 0) {
        (del) ? del(p) : delete p;
        delete use;
    } 
    p = nullptr;
    use = nullptr;
}

template <typename T>
std::ostream& operator<<(std::ostream& os, shared_ptr<T> ptr)
{
    return os << ptr.get();
}

template <typename T>
bool operator==(const shared_ptr<T>& lhs, const shared_ptr<T>& rhs)
{
    return lhs.get() == rhs.get();
}

template <typename T>
bool operator==(const shared_ptr<T>& ptr, std::nullptr_t)
{
    return !ptr;
}

template <typename T>
bool operator!=(const shared_ptr<T>& lhs, const shared_ptr<T>& rhs)
{
    return !(lhs == rhs);
}

template <typename T>
bool operator!=(const shared_ptr<T>& ptr, std::nullptr_t)
{
    return ptr;
}

template <typename T>
bool operator<(const shared_ptr<T>& lhs, const shared_ptr<T>& rhs)
{
    return std::less<T*>()(lhs.get(), rhs.get());
}

#endif // SHARED_PTR_H

/*
 * NOTE: This implementation is modelled on cppreference.org specifications,
 * with one exception: when swapping two unique_ptr, the deleter is not swapped.
 * This seems to simplify, the reset operation. Since the type of the deleter
 * is part of the pointer's type, any operations that takes a binary parameter,
 * such as move, swap, or reset, must have the types of its parameter match.
 * Therefore, it is unnecessary to copy the deleter because the destination's
 * deleter will always match the source's. This seems acceptable for the time
 * being.
 * Refer to https://en.cppreference.com/w/cpp/memory/unique_ptr
 * To simplify the code, the implementation uses a small set of key operations,
 * such as get, swap, operator boo() to perform the other operations. The
 * deleter is stored directly as class data member.
 */

#ifndef UNIQUE_PTR_H
#define UNIQUE_PTR_H

#include <functional>
#include <memory>
#include <ostream>

template <typename T, typename D = std::default_delete<T>>
class unique_ptr {
    public:
        unique_ptr() = default;
        unique_ptr(std::nullptr_t, D d = std::default_delete<T>()) noexcept : del(d) {}
        explicit unique_ptr(T* ptr) : p(ptr) {}
        explicit unique_ptr(T* ptr, D d) : p(ptr), del(d) {}
        unique_ptr(const unique_ptr&) = delete;
        unique_ptr(unique_ptr&& ptr) noexcept;
        unique_ptr& operator=(const unique_ptr&) = delete;
        unique_ptr& operator=(unique_ptr&&) noexcept;
        ~unique_ptr() { del(p); }
        T* get() const noexcept { return p; }
        void swap(unique_ptr&) noexcept;
        T* release();
        void reset(T* q = nullptr) noexcept;
        operator bool() const noexcept { return this->get() != nullptr; }
        T& operator*() const { return *p; };
        T* operator->() const noexcept { return & this->operator*(); };
    public:
        T* p = nullptr;
        D del;
};

template <typename T, typename D>
unique_ptr<T, D>::unique_ptr(unique_ptr&& ptr) noexcept : p(ptr.p), del(ptr.del)
{
    ptr.p = nullptr;
}

template <typename T, typename D>
unique_ptr<T, D>&
unique_ptr<T, D>::operator=(unique_ptr&& rhs) noexcept
{
    if (this != &rhs)
        unique_ptr<T, D>(std::move(rhs)).swap(*this);
    return *this;
}

template <typename T, typename D>
void unique_ptr<T, D>::swap(unique_ptr& ptr) noexcept
{
    using std::swap;
    swap(p, ptr.p);
//  the deleter is not swapped
}

template <typename T, typename D>
T* unique_ptr<T, D>::release()
{
    auto ret = this->get();
    this->p = nullptr;
    return ret;
}

template <typename T, typename D>
void unique_ptr<T, D>::reset(T* q) noexcept
{
    unique_ptr<T, D>(q).swap(*this); // note: del is not swapped
}

template <typename T, typename D>
bool operator==(const unique_ptr<T, D>& lhs, const unique_ptr<T, D>& rhs)
{
    return lhs.get() == rhs.get();
}

template <typename T, typename D>
bool operator==(const unique_ptr<T, D>& ptr, std::nullptr_t)
{
    return !ptr;
}

template <typename T, typename D>
bool operator!=(const unique_ptr<T, D>& lhs, const unique_ptr<T, D>& rhs)
{
    return !(lhs == rhs);
}

template <typename T, typename D>
bool operator!=(const unique_ptr<T, D>& ptr, std::nullptr_t)
{
    return ptr;
}

template <typename T, typename D>
bool operator<(const unique_ptr<T, D>& lhs, const unique_ptr<T, D>& rhs)
{
    return std::less<T*>()(lhs.get(), rhs.get());
}

template <typename T, typename D>
std::ostream& operator<<(std::ostream& os, const unique_ptr<T, D>& ptr)
{
    return os << ptr.get();
}

#endif // UNIQUE_PTR_H

